"use client";
import { useEffect, useState } from "react";
import { Users, Activity, TrendingUp, Clock } from "lucide-react";
import Link from "next/link";
import { formatDistanceToNow } from "date-fns";

export default function Home() {
  const [stats, setStats] = useState<any>(null);
  const [feed, setFeed] = useState<any[]>([]);

  useEffect(() => {
    fetch('/api/stats').then(res => res.json()).then(setStats);
    fetch('/api/feed').then(res => res.json()).then(setFeed);

    const interval = setInterval(() => {
      fetch('/api/feed').then(res => res.json()).then(setFeed);
    }, 10000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="space-y-8">
      <div>
        <h1 className="text-3xl font-bold mb-2">Dashboard</h1>
        <p className="text-zinc-400">Live feed and high-level metrics of tracked users.</p>
      </div>

      {stats && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="bg-zinc-900 border border-zinc-800 p-6 rounded-xl flex items-center gap-4">
            <div className="p-3 bg-blue-500/10 text-blue-400 rounded-lg"><Users className="w-6 h-6" /></div>
            <div>
              <p className="text-sm text-zinc-400">Users Tracked</p>
              <p className="text-2xl font-bold">{stats.usersTracked.toLocaleString()}</p>
            </div>
          </div>
          <div className="bg-zinc-900 border border-zinc-800 p-6 rounded-xl flex items-center gap-4">
            <div className="p-3 bg-green-500/10 text-green-400 rounded-lg"><Activity className="w-6 h-6" /></div>
            <div>
              <p className="text-sm text-zinc-400">Trades Stored</p>
              <p className="text-2xl font-bold">{stats.tradesStored.toLocaleString()}</p>
            </div>
          </div>
          <div className="bg-zinc-900 border border-zinc-800 p-6 rounded-xl flex items-center gap-4">
            <div className="p-3 bg-purple-500/10 text-purple-400 rounded-lg"><TrendingUp className="w-6 h-6" /></div>
            <div>
              <p className="text-sm text-zinc-400">Big Bet Users (24h)</p>
              <p className="text-2xl font-bold">{stats.bigBetUsers24h.toLocaleString()}</p>
            </div>
          </div>
        </div>
      )}

      <div>
        <h2 className="text-xl font-bold mb-4 flex items-center gap-2"><Clock className="w-5 h-5" /> Live Trade Feed</h2>
        <div className="bg-zinc-900 border border-zinc-800 rounded-xl overflow-hidden">
          <table className="w-full text-left text-sm">
            <thead className="bg-zinc-800/50 text-zinc-400">
              <tr>
                <th className="px-4 py-3">Time</th>
                <th className="px-4 py-3">User</th>
                <th className="px-4 py-3">Side</th>
                <th className="px-4 py-3">Market</th>
                <th className="px-4 py-3 text-right">Size</th>
                <th className="px-4 py-3 text-right">Price</th>
                <th className="px-4 py-3 text-right">Notional</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-zinc-800">
              {feed.map(t => (
                <tr key={t.id} className="hover:bg-zinc-800/50 transition-colors">
                  <td className="px-4 py-3 text-zinc-400 whitespace-nowrap">{formatDistanceToNow(new Date(t.timestamp * 1000), { addSuffix: true })}</td>
                  <td className="px-4 py-3">
                    <Link href={`/users/${t.proxyWallet}`} className="text-blue-400 hover:underline">
                      {t.u_pseudonym || t.u_name || (t.proxyWallet.slice(0, 6) + '...' + t.proxyWallet.slice(-4))}
                    </Link>
                  </td>
                  <td className="px-4 py-3">
                    <span className={`px-2 py-1 rounded text-xs font-bold ${t.side === 'BUY' ? 'bg-green-500/20 text-green-400' : 'bg-red-500/20 text-red-400'}`}>
                      {t.side} {t.outcome}
                    </span>
                  </td>
                  <td className="px-4 py-3 max-w-xs truncate" title={t.title}>{t.title}</td>
                  <td className="px-4 py-3 text-right">{t.size.toLocaleString()}</td>
                  <td className="px-4 py-3 text-right">${t.price.toFixed(3)}</td>
                  <td className="px-4 py-3 text-right font-medium">${(t.size * t.price).toFixed(2)}</td>
                </tr>
              ))}
            </tbody>
          </table>
          {feed.length === 0 && <div className="p-8 text-center text-zinc-500">No trades collected yet. Run the crawler.</div>}
        </div>
      </div>
    </div>
  );
}

"use client";
import { useEffect, useState, useCallback } from "react";
import Link from "next/link";
import { Search, ChevronDown, ChevronUp } from "lucide-react";
import { formatDistanceToNow } from "date-fns";

export default function UsersPage() {
  const [users, setUsers] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [q, setQ] = useState("");
  const [newWithinDays, setNewWithinDays] = useState("0");
  const [minSingleBet, setMinSingleBet] = useState("100");
  const [minVolume, setMinVolume] = useState("0");
  const [sortBy, setSortBy] = useState("total_notional");
  const [order, setOrder] = useState("desc");

  const fetchUsers = useCallback(async () => {
    setLoading(true);
    const params = new URLSearchParams({
      q, newWithinDays, minSingleBet, minVolume, sortBy, order
    });
    const res = await fetch(`/api/users?${params}`);
    const data = await res.json();
    setUsers(data.data || []);
    setLoading(false);
  }, [q, newWithinDays, minSingleBet, minVolume, sortBy, order]);

  useEffect(() => {
    fetchUsers();
  }, [fetchUsers]);

  const toggleSort = (col: string) => {
    if (sortBy === col) {
      setOrder(order === "desc" ? "asc" : "desc");
    } else {
      setSortBy(col);
      setOrder("desc");
    }
  };

  const SortIcon = ({ col }: { col: string }) => {
    if (sortBy !== col) return null;
    return order === "desc" ? <ChevronDown className="w-4 h-4 inline" /> : <ChevronUp className="w-4 h-4 inline" />;
  };

  return (
    <div className="space-y-6">
      <h1 className="text-3xl font-bold">User Directory</h1>

      <div className="bg-zinc-900 border border-zinc-800 p-4 rounded-xl flex flex-wrap gap-4 items-end">
        <div className="flex-1 min-w-[200px]">
          <label className="block text-sm text-zinc-400 mb-1">Search Wallet/Name</label>
          <div className="relative">
            <Search className="w-4 h-4 absolute left-3 top-3 text-zinc-500" />
            <input type="text" value={q} onChange={e => setQ(e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg pl-9 pr-4 py-2 focus:outline-none focus:border-blue-500" placeholder="0x..." />
          </div>
        </div>
        <div>
          <label className="block text-sm text-zinc-400 mb-1">New User (Days)</label>
          <select value={newWithinDays} onChange={e => setNewWithinDays(e.target.value)} className="bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-2 focus:outline-none focus:border-blue-500">
            <option value="0">Any time</option>
            <option value="1">Last 24 hours</option>
            <option value="7">Last 7 days</option>
            <option value="30">Last 30 days</option>
          </select>
        </div>
        <div>
          <label className="block text-sm text-zinc-400 mb-1">Min Single Bet ($)</label>
          <input type="number" value={minSingleBet} onChange={e => setMinSingleBet(e.target.value)} className="w-32 bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-2 focus:outline-none focus:border-blue-500" />
        </div>
        <div>
          <label className="block text-sm text-zinc-400 mb-1">Min Volume ($)</label>
          <input type="number" value={minVolume} onChange={e => setMinVolume(e.target.value)} className="w-32 bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-2 focus:outline-none focus:border-blue-500" />
        </div>
      </div>

      <div className="bg-zinc-900 border border-zinc-800 rounded-xl overflow-x-auto">
        <table className="w-full text-left text-sm">
          <thead className="bg-zinc-800/50 text-zinc-400">
            <tr>
              <th className="px-4 py-3">User</th>
              <th className="px-4 py-3 cursor-pointer select-none" onClick={() => toggleSort('first_seen')}>First Seen <SortIcon col="first_seen" /></th>
              <th className="px-4 py-3 cursor-pointer select-none" onClick={() => toggleSort('trade_count')}>Trades <SortIcon col="trade_count" /></th>
              <th className="px-4 py-3 cursor-pointer select-none text-right" onClick={() => toggleSort('total_notional')}>Total Vol <SortIcon col="total_notional" /></th>
              <th className="px-4 py-3 cursor-pointer select-none text-right" onClick={() => toggleSort('max_single_bet')}>Max Bet <SortIcon col="max_single_bet" /></th>
              <th className="px-4 py-3 cursor-pointer select-none text-right" onClick={() => toggleSort('last_active')}>Last Active <SortIcon col="last_active" /></th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-800">
            {loading ? (
              <tr><td colSpan={6} className="p-8 text-center text-zinc-500">Loading...</td></tr>
            ) : users.length === 0 ? (
              <tr><td colSpan={6} className="p-8 text-center text-zinc-500">No users found.</td></tr>
            ) : (
              users.map(u => (
                <tr key={u.wallet} className="hover:bg-zinc-800/50 transition-colors">
                  <td className="px-4 py-3">
                    <Link href={`/users/${u.wallet}`} className="text-blue-400 hover:underline font-medium">
                      {u.pseudonym || u.name || (u.wallet.slice(0, 6) + '...' + u.wallet.slice(-4))}
                    </Link>
                  </td>
                  <td className="px-4 py-3">{formatDistanceToNow(new Date(u.first_seen * 1000), { addSuffix: true })}</td>
                  <td className="px-4 py-3">{u.trade_count.toLocaleString()}</td>
                  <td className="px-4 py-3 text-right">${u.total_notional.toLocaleString(undefined, { maximumFractionDigits: 0 })}</td>
                  <td className="px-4 py-3 text-right text-emerald-400">${u.max_single_bet.toLocaleString(undefined, { maximumFractionDigits: 0 })}</td>
                  <td className="px-4 py-3 text-right">{formatDistanceToNow(new Date(u.last_active * 1000), { addSuffix: true })}</td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

"use client";
import { useEffect, useState } from "react";
import Link from "next/link";
import { Trophy } from "lucide-react";

export default function LeaderboardPage() {
  const [data, setData] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [window, setWindow] = useState("1w");

  useEffect(() => {
    setLoading(true);
    fetch(`/api/leaderboard?window=${window}`)
      .then(res => res.json())
      .then(d => {
        setData(d || []);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, [window]);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h1 className="text-3xl font-bold flex items-center gap-3"><Trophy className="w-8 h-8 text-yellow-500"/> Leaderboard</h1>
        <div className="bg-zinc-900 rounded-lg p-1 border border-zinc-800 inline-flex">
          {["1d", "1w", "1m", "all"].map(w => (
            <button 
              key={w} 
              onClick={() => setWindow(w)} 
              className={`px-4 py-1.5 rounded-md text-sm font-medium transition-colors ${window === w ? 'bg-zinc-800 text-white' : 'text-zinc-400 hover:text-zinc-200'}`}
            >
              {w.toUpperCase()}
            </button>
          ))}
        </div>
      </div>

      <div className="bg-zinc-900 border border-zinc-800 rounded-xl overflow-hidden">
        <table className="w-full text-left text-sm">
          <thead className="bg-zinc-800/50 text-zinc-400">
            <tr>
              <th className="px-4 py-3 w-16 text-center">Rank</th>
              <th className="px-4 py-3">User</th>
              <th className="px-4 py-3 text-right">Volume</th>
              <th className="px-4 py-3 text-right">PnL</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-800">
            {loading ? (
              <tr><td colSpan={4} className="p-8 text-center text-zinc-500">Loading leaderboard...</td></tr>
            ) : data.length === 0 ? (
              <tr><td colSpan={4} className="p-8 text-center text-zinc-500">No data available.</td></tr>
            ) : (
              data.map((row: any, i) => (
                <tr key={i} className="hover:bg-zinc-800/50 transition-colors">
                  <td className="px-4 py-3 text-center font-bold text-zinc-400">{i + 1}</td>
                  <td className="px-4 py-3">
                    <Link href={`/users/${row.proxyWallet}`} className="text-blue-400 hover:underline font-medium">
                      {row.userName || (row.proxyWallet.slice(0, 6) + '...' + row.proxyWallet.slice(-4))}
                    </Link>
                  </td>
                  <td className="px-4 py-3 text-right">${parseFloat(row.amount || 0).toLocaleString(undefined, {maximumFractionDigits:0})}</td>
                  <td className={`px-4 py-3 text-right font-bold ${parseFloat(row.pnl || 0) >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                    {parseFloat(row.pnl || 0) >= 0 ? '+' : ''}${parseFloat(row.pnl || 0).toLocaleString(undefined, {maximumFractionDigits:0})}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

